pub fn command(name: &str) -> Option<&'static CommandMeta> {
    COMMANDS.iter().find(|c| c.name == name)
}

pub fn permission(node: &str) -> Option<&'static PermMeta> {
    PERMISSIONS.binary_search_by(|p| p.node.cmp(node)).ok().map(|i| &PERMISSIONS[i])
}
